style.css:
@-moz-document domain("youtube.com") {
/* 1. OVERRIDE YOUTUBE'S CORE DARK MODE COLORS */
    html:not(.style-scope)[dark], :root {
        /* Core Backgrounds - Gritty Olive Greens */
        --yt-spec-base-background: #343c33 !important;       /* Main site background */
        --yt-spec-raised-background: #4b5b42 !important;     /* Hover states / panels */
        --yt-spec-menu-background: #414f39 !important;       /* Dropdown menus */
        --yt-spec-inverted-background: #2a3325 !important;   /* Tooltips */

        /* Text & Links - Off-white and Gold */
        --yt-spec-text-primary: #e0e0e0 !important;          /* Main titles */
        --yt-spec-text-secondary: #c1b476 !important;        /* Gold for views/dates */
        --yt-spec-call-to-action: #c1b476 !important;        /* Buttons */
        
        /* Borders & Lines */
        --yt-spec-10-percent-layer: rgba(122, 140, 106, 0.4) !important; /* Dividers */
        
        /* The Top Navigation Chips (Toate, Muzică, etc.) */
        --yt-spec-badge-chip-background: #2a3325 !important;
        --yt-spec-button-chip-background-hover: #7a8c6a !important;
        
        /* Search Box */
        --ytd-searchbox-background: #1a1f18 !important;
        --ytd-searchbox-text-color: #e0e0e0 !important;
    }

    /* 2. FORCE THE TOP BAR & SIDEBAR TO MATCH THE VIBE */
    #masthead-container.ytd-app {
        background-color: #1a1f18 !important;
        border-bottom: 2px solid #7a8c6a !important;
    }
    
    #guide-content.ytd-app, 
    app-drawer#guide {
        background-color: #2a3325 !important;
        border-right: 1px solid #7a8c6a !important;
    }

    /* 3. TURN THE YOUTUBE LOGO GREEN */
    ytd-topbar-logo-renderer {
        filter: hue-rotate(250deg) saturate(3) brightness(1.2) !important;
    }

    /* 4. MAKE ICONS GOLD */
    yt-icon, .yt-icon-container {
        color: #c1b476 !important; 
    }

    /* 5. MAKE THUMBNAILS RIGID (Removes modern rounded corners, adds borders) */
    ytd-thumbnail {
        border: 2px solid #4b5b42 !important;
        border-radius: 0px !important;
    }
    ytd-thumbnail #thumbnail.ytd-thumbnail {
        border-radius: 0px !important;
    }
    ytd-thumbnail:hover {
        border-color: #c1b476 !important; /* Thumbnail border turns gold on hover */
    }

    /* 6. SEARCH BAR BORDERS */
    #container.ytd-searchbox {
        border: 1px solid #7a8c6a !important;
        border-radius: 0px !important;
    }
    #search-icon-legacy.ytd-searchbox {
        border: 1px solid #7a8c6a !important;
        border-radius: 0px !important;
        background-color: #2a3325 !important;
    }
}
